import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../frontend/national-film-awards-explorer",e),"utf-8")}function readSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function(e+"\nreturn window.indiaSearchIndex;")()}describe("National Film Awards Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with title and key stats",()=>{expect(e).toContain('class="nfa-hero"'),expect(e).toContain("National Film Awards Explorer"),expect(e).toContain("nfa-hero-stats")}),it("contains all required content sections",()=>{["History","Categories","Best Feature Film","Acting Awards","Technical Awards","Selection Process","Timeline","Notable Winners","Image Gallery"].forEach(t=>{expect(e).toContain(t)})}),it("has navigation tabs wired to sections",()=>{expect(e).toContain('data-tab="history"'),expect(e).toContain('data-tab="categories"'),expect(e).toContain('data-tab="feature-film"'),expect(e).toContain('data-tab="acting"'),expect(e).toContain('data-tab="technical"'),expect(e).toContain('data-tab="selection"'),expect(e).toContain('data-tab="timeline"'),expect(e).toContain('data-tab="winners"'),expect(e).toContain('data-tab="gallery"'),expect(e).toContain('id="history" class="nfa-section active"')}),it("documents the award establishment and medal structure",()=>{expect(e).toContain("Established in <strong>1954</strong>"),expect(e).toContain("Swarna Kamal (Golden Lotus)"),expect(e).toContain("Rajat Kamal (Silver Lotus)")}),it("includes key historical facts",()=>{expect(e).toContain("Shyamchi Aai"),expect(e).toContain("Satyajit Ray"),expect(e).toContain("Uttam Kumar"),expect(e).toContain("Nargis")}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('type="module" src="script.js"')})}),describe("National Film Awards Explorer — Assets & Scripts",()=>{it("includes non-empty stylesheet with theme and responsive styles",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".nfa-page-body"),expect(e).toContain(".nfa-hero"),expect(e).toContain(".light-theme .nfa-content-card"),expect(e).toContain("@media")}),it("includes interactive script with tab, theme, and menu functions",()=>{const e=readExplorerFile("script.js");expect(e.length).toBeGreaterThan(500),expect(e).toContain("initTabNavigation"),expect(e).toContain("initThemeToggle"),expect(e).toContain("initMobileMenu")})}),describe("Awards of India Explorer Landing Page Integration",()=>{it("contains a National Film Awards card linking to the explorer",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("National Film Awards"),expect(e).toContain("Instituted: 1954"),expect(e).toContain('href="../national-film-awards-explorer/index.html"'),expect(e).toContain('class="award-card glass-card"')})}),describe("Search Index Integration",()=>{it("registers the National Film Awards Explorer for site search",()=>{const e=readSearchIndex().find(e=>"National Film Awards Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/national-film-awards-explorer/index.html"),expect(e.category).toBe("Awards & Honours")})});